arnival_Pack[nItemId]) then				WarriorsPromotion_JudgeNinjaItem(nItemId)			end		else			--提示			Sys_MsgBox(string.format(tPeelingPromotion_Text["MsgSpace"],nSpace))			return 		end	else				--有返利,给玩家返相应的天石		-- if nCutTip == 2 then		local nEmoney = Get_UserMonoEMoney()		if nEmoney + nReturnMoney > G_User_MaxEmoneyMono then			User_TalkChannel2005(tMayPKMonth_Text["Item"]["Text141"])			Sys_MsgBox(tMayPKMonth_Text["Item"]["Text141"])			return		end		-- end				if User_CheckLeftSpace(nSpace) then			RewardTemplate_UseItemAndMsg(tSuitMountCarnival_Pack[nItemId])			--给玩家对应的印记			-- CommonPackage_LocationYing(nItemId,nCutTip)					--若是玩家有打折卷则给玩家放对应的天石			-- if nCutTip == 2  then				--给对应的天石			if CommonPackage_DeleteTicket(nZhengItemId,nItemId) and User_AddEMoneyMono(nReturnMoney) then				Sys_SaveEmoneyBuy(string.format(sEmoneyLog,nReturnMoney))			end			-- end		else			User_TalkChannel2005(string.format(tRewardTemplate_Text["NoSpace"],nSpace))			Sys_MsgBox(string.format(tRewardTemplate_Text["NoSpace"],nSpace))		end			end	end